import json,sys
sys.path.insert(0,'.')
def C(title,scen,prompt,cues,target,en,can):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scen,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":can}
d={
'b2-nicaragua-01':C('Why an Eight?','You are Meg. You and Carlos are planning a trip to Nicaragua, and he asks you why the island of Ometepe looks so strange on the map.','Tell Carlos why Ometepe is shaped like an eight.',['Say what shape the island has','Give the reason'],'Ometepe tiene forma de ocho porque la forman dos volcanes.','Ometepe is shaped like an eight because two volcanoes form it.','I can give a reason with *porque* and a result with *por eso*.'),
'b2-nicaragua-02':C('Where Darío Died','You are Carlos. You and Meg are listening to a talk about Rubén Darío, and she asks you where and when he died.','Tell Meg where and when Darío died, putting the place first.',['Start with the place','Say who died and when'],'En León murió Rubén Darío, en febrero de 1916.','In León Rubén Darío died, in February 1916.','I can put an adjective, a place or a time first to stress it, as in *Decisiva fue…*.'),
'b2-nicaragua-03':C('What If?','You are Meg. You and Carlos are watching a documentary about Sandino, and he asks you what you think about the pact of Tipitapa.','Tell Carlos what would have happened if Sandino had accepted the pact.',['Start with the condition','Say what he would not have done'],'Si Sandino hubiera aceptado el pacto, no habría luchado en las montañas.','If Sandino had accepted the pact, he would not have fought in the mountains.','I can say what would have happened if something had been different, with *si hubiera… habría…*.'),
'b2-nicaragua-04':C('Painters in Spite of Everything','You are Carlos. You and Meg are reading an article about Solentiname, and she asks you why the paintings are special.','Tell Meg what the peasants of Solentiname did in spite of their situation.',['Say what they were not','Say what they began to do'],'A pesar de no tener estudios de arte, los campesinos de Solentiname empezaron a pintar.','Although they had no art training, the peasants of Solentiname began to paint.','I can say that something continued in spite of a difficulty, with *a pesar de* and *pese a*.'),
'b2-nicaragua-05':C('Who Says What','You are Meg. You and Carlos are reading the news about Nicaragua, and he asks you what is known about the 2018 protests.','Tell Carlos what the UN said and what the government said, naming each source.',['Give the UN source and a number','Say what the government said'],'Según la ONU, murieron más de trescientas personas. El gobierno dijo que las protestas eran un intento de golpe de Estado.','According to the UN, more than three hundred people died. The government said the protests were an attempt at a coup.','I can say who said what, with *según* and *dijo que*.'),
'b2-nicaragua-consolidation':C('Review: Nicaragua','You are Carlos. You and Meg are planning a trip to Nicaragua, and she asks what you remember about the lake and about Darío.','Tell Meg one fact about each.',['Say why the lake has waves','Say where Darío died, putting the place first'],'El lago es muy grande; por eso a veces tiene olas. En León murió Rubén Darío.','The lake is very big; that is why it sometimes has waves. In León Rubén Darío died.','I can review what I learned about Nicaragua, from Lake Cocibolca to the present day.')}
json.dump(d,open('/home/user/parlour-read-a/challenges-nicaragua.json','w'),ensure_ascii=False,indent=2)
